import { crc32, PNG_SIGNATURE } from './png.js';

// Images for tests, fixtures and local manual testing, generated by our own
// code. No Jagex graphics may ever appear in the repo (see docs/legal.md), so
// every image byte sequence in fixtures and tests comes from here, and
// `fixtures.test.ts` checks that the fixtures are byte-identical to this output.
// Plain TypeScript with uncompressed (stored) deflate, so the bytes are the same
// on every Node and zlib version.

/** RGBA colour, 0–255 per channel. */
export type Rgba = readonly [number, number, number, number];

function u32(value: number): number[] {
  return [(value >>> 24) & 0xff, (value >>> 16) & 0xff, (value >>> 8) & 0xff, value & 0xff];
}

function concat(parts: readonly (Uint8Array | readonly number[])[]): Uint8Array {
  const total = parts.reduce((sum, part) => sum + part.length, 0);
  const out = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

/** One PNG chunk: length, type, data and CRC. `badCrc` flips the CRC. */
export function pngChunk(type: string, data: Uint8Array | readonly number[] = [], badCrc = false) {
  const typeBytes = Array.from(type, (char) => char.charCodeAt(0));
  const body = concat([typeBytes, data]);
  const crc = crc32(body) ^ (badCrc ? 0xffffffff : 0);
  return concat([u32(data.length), body, u32(crc >>> 0)]);
}

/** zlib stream with stored (uncompressed) deflate blocks. */
function zlibStored(data: Uint8Array): Uint8Array {
  const parts: (Uint8Array | number[])[] = [[0x78, 0x01]];
  const blocks = Math.max(1, Math.ceil(data.length / 0xffff));
  for (let i = 0; i < blocks; i++) {
    const block = data.subarray(i * 0xffff, (i + 1) * 0xffff);
    const n = block.length;
    const last = i === blocks - 1 ? 1 : 0;
    parts.push([last, n & 0xff, n >>> 8, ~n & 0xff, (~n >>> 8) & 0xff], block);
  }
  let a = 1;
  let b = 0;
  for (const byte of data) {
    a = (a + byte) % 65521;
    b = (b + a) % 65521;
  }
  parts.push(u32(((b << 16) | a) >>> 0));
  return concat(parts);
}

export interface SolidPngOptions {
  /**
   * `indexed` (default): one palette entry, small enough for 64×64 under 16 KB.
   * `rgba`: 8-bit truecolour with alpha, 4 bytes per pixel.
   */
  format?: 'indexed' | 'rgba';
  /** Chunks inserted before IEND (e.g. `acTL`, padding). */
  extraChunks?: readonly Uint8Array[];
  /** Leave out IEND. */
  omitIend?: boolean;
  /** Corrupt the IHDR CRC. */
  badIhdrCrc?: boolean;
}

/** A single-colour PNG square or rectangle. */
export function makeSolidPng(
  width: number,
  height: number,
  rgba: Rgba,
  options: SolidPngOptions = {},
): Uint8Array {
  const format = options.format ?? 'indexed';
  const indexed = format === 'indexed';
  const ihdr = [...u32(width), ...u32(height), 8, indexed ? 3 : 6, 0, 0, 0];
  const rowBytes = indexed ? width : width * 4;
  const raw = new Uint8Array(height * (rowBytes + 1));
  for (let y = 0; y < height; y++) {
    const row = y * (rowBytes + 1); // filter byte 0 (none), then pixels
    if (!indexed) {
      for (let x = 0; x < width; x++) raw.set(rgba, row + 1 + x * 4);
    }
  }
  const chunks: Uint8Array[] = [pngChunk('IHDR', ihdr, options.badIhdrCrc)];
  if (indexed) {
    chunks.push(pngChunk('PLTE', rgba.slice(0, 3)));
    if (rgba[3] !== 255) chunks.push(pngChunk('tRNS', [rgba[3]]));
  }
  chunks.push(pngChunk('IDAT', zlibStored(raw)));
  chunks.push(...(options.extraChunks ?? []));
  if (!options.omitIend) chunks.push(pngChunk('IEND'));
  return concat([PNG_SIGNATURE, ...chunks]);
}

/** A 1×1 GIF89a with a two-colour palette (for wrong-format tests). */
export function makeTinyGif(rgb: readonly [number, number, number]): Uint8Array {
  return concat([
    Array.from('GIF89a', (char) => char.charCodeAt(0)),
    [1, 0, 1, 0, 0x80, 0, 0], // 1×1, global colour table of 2 entries
    [...rgb, 0, 0, 0],
    [0x2c, 0, 0, 0, 0, 1, 0, 1, 0, 0], // image descriptor
    [2, 2, 0x44, 0x01, 0], // LZW minimum code size 2, one sub-block, terminator
    [0x3b], // trailer
  ]);
}

/**
 * An 8×8 baseline greyscale JPEG in mid grey (for wrong-format tests). One
 * Huffman code each for DC difference 0 and end-of-block, so the scan is a
 * single byte.
 */
export function makeTinyJpeg(): Uint8Array {
  const segment = (marker: number, data: readonly number[]) => [
    0xff,
    marker,
    (data.length + 2) >>> 8,
    (data.length + 2) & 0xff,
    ...data,
  ];
  const lengths = (first: number) => [first, ...new Array<number>(15).fill(0)];
  return concat([
    [0xff, 0xd8], // SOI
    segment(0xe0, [0x4a, 0x46, 0x49, 0x46, 0, 1, 1, 0, 0, 1, 0, 1, 0, 0]), // JFIF
    segment(0xdb, [0, ...new Array<number>(64).fill(1)]), // quantisation table 0
    segment(0xc0, [8, 0, 8, 0, 8, 1, 1, 0x11, 0]), // SOF0: 8×8, one component
    segment(0xc4, [0x00, ...lengths(1), 0x00]), // DC table 0: symbol 0
    segment(0xc4, [0x10, ...lengths(1), 0x00]), // AC table 0: end of block
    segment(0xda, [1, 1, 0x00, 0, 63, 0]), // SOS
    [0x3f], // DC diff 0, EOB, padded with ones
    [0xff, 0xd9], // EOI
  ]);
}
